def user_from_dict(d: Mapping[str, object]) -> User:
    return User(id=int(d["id"]),                       # explicit, fail-loud reads
                full_name=str(d["full_name"]),
                admin=bool(d.get("is_admin", False)))

def user_to_dict(u: User) -> dict[str, object]:
    return {"id": u.id, "full_name": u.full_name, "is_admin": u.admin}
